import objectHash from 'object-hash';
import {
  Bundler,
  BundlerContext,
  DevServer,
  DevServerContext,
} from '@teambit/bundler';
import { EnvHandler } from '@teambit/envs';
import { EnvPreviewConfig, Preview } from '@teambit/preview';
import { RspackConfigTransformer } from '@teambit/rspack.modules.rspack-config-mutator';
import { RspackDevServer } from '@teambit/rspack.rspack-dev-server';
import { RspackBundler } from '@teambit/rspack.rspack-bundler';
import { ReactPreviewOptions } from './react-preview-config';
import { createCacheControlTransformer } from './rspack-caching.transformer';
import { createErrorReportingTransformer } from './rspack-error-reporting.transformer';
import { createHmrTransformer } from './rspack-hmr.transformer';
import { createReactDomProfilingToClientAliasTransformer } from './rspack-react-dom-profiling-to-client-alias.transformer';

export class ReactPreview implements Preview {
  constructor(
    readonly name: string,
    protected mounter: string = require.resolve('./mounter'),
    protected docsTemplate: string = require.resolve('./docs'),
    protected previewConfig: EnvPreviewConfig = {},
    protected transformers: RspackConfigTransformer[] = [],
    protected hostDependencies?: string[],
    protected devServer?: DevServer,
    protected bundler?: Bundler,
    protected rspackModulePath: string = require.resolve('@rspack/core'),
    protected rspackDevServerModulePath: string = require.resolve(
      '@rspack/dev-server'
    ),
    protected useSource: boolean = true
  ) {}

  /**
   * Default host dependencies for the react preview.
   */
  static hostDependencies = [
    '@teambit/mdx.ui.mdx-scope-context',
    '@mdx-js/react',
    'react',
    'react-dom'
  ];

  getDevServer(context: DevServerContext): EnvHandler<DevServer> {
    if (this.devServer) return () => this.devServer!;

    return RspackDevServer.from({
      rspackModulePath: this.rspackModulePath,
      rspackDevServerModulePath: this.rspackDevServerModulePath,
      devServerContext: context,
      transformers: [
        createCacheControlTransformer(),
        createErrorReportingTransformer(),
        createHmrTransformer(),
        createReactDomProfilingToClientAliasTransformer(),
        ...this.transformers,
      ],
    });
  }

  getDevEnvId(): string {
    const objToHash = {
      rspackModulePath: this.rspackModulePath,
      rspackDevServerModulePath: this.rspackDevServerModulePath,
      transformers: this.transformers,
      hostDependencies: this.getHostDependencies().sort(),
    };
    const devEnvId = objectHash(objToHash);
    return devEnvId;
  }

  getBundler(context: BundlerContext): EnvHandler<Bundler> {
    if (this.bundler) return () => this.bundler!;
    return RspackBundler.from({
      targets: context.targets,
      transformers: [createReactDomProfilingToClientAliasTransformer(), ...this.transformers],
      bundlerContext: context,
      rspackModulePath: this.rspackModulePath,
    });
  }

  getTemplateBundler(context: BundlerContext): EnvHandler<Bundler> {
    return RspackBundler.from({
      targets: context.targets,
      transformers: [createReactDomProfilingToClientAliasTransformer(), ...this.transformers],
      bundlerContext: context,
      rspackModulePath: this.rspackModulePath,
    });
  }

  getHostDependencies(): string[] {
    return this.hostDependencies || ReactPreview.hostDependencies;
  }

  getMounter(): string {
    return this.mounter;
  }

  getDocsTemplate(): string {
    return this.docsTemplate;
  }

  getPreviewConfig(): EnvPreviewConfig {
    return {
      strategyName: 'component',
      splitComponentBundle: true,
      // @ts-ignore - supportsUseSource is not yet in EnvPreviewConfig type
      supportsUseSource: this.useSource,
      ...this.previewConfig,
    };
  }

  static from(options: ReactPreviewOptions): EnvHandler<ReactPreview> {
    const name = options.name || 'react-preview';

    return () => {
      return new ReactPreview(
        name,
        options.mounter,
        options.docsTemplate,
        options.previewConfig,
        options.transformers,
        options.hostDependencies,
        options.devServer,
        options.bundler,
        options.rspackModulePath,
        options.rspackDevServerModulePath,
        options.useSource ?? true
      );
    };
  }
}
